def transform(grid):
    # Complete the perimeter of the sparse rectangle in color 2. Some puzzles
    # also include an interrupted interior vertical stroke anchored on both
    # horizontal edges; complete that stroke too.
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    fg = Counter(v for row in grid for v in row if v != bg).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == fg]
    top = min(r for r, c in points)
    bottom = max(r for r, c in points)
    left = min(c for r, c in points)
    right = max(c for r, c in points)
    out = [row[:] for row in grid]
    for c in range(left, right + 1):
        if out[top][c] == bg:
            out[top][c] = 2
        if out[bottom][c] == bg:
            out[bottom][c] = 2
    verticals = {left, right}
    for c in range(left + 1, right):
        if (grid[top][c] == fg and grid[bottom][c] == fg
                and any(grid[r][c] == fg for r in range(top + 1, bottom))):
            verticals.add(c)
    for c in verticals:
        for r in range(top, bottom + 1):
            if out[r][c] == bg:
                out[r][c] = 2
    return out

